import java.util.*;

class Solution {
    public int maxSubArray(int[] profit) {
        int cur = profit[0], best = profit[0];
        for (int i = 1; i < profit.length; i++) {
            cur = Math.max(profit[i], cur + profit[i]); // extend or start fresh today
            best = Math.max(best, cur);
        }
        return best;
    }
}

