function maxSubArray(a) {
  const pre = [0]; for (const x of a) pre.push(pre[pre.length - 1] + x);
  let best = -Infinity, mn = 0;
  for (let j = 1; j < pre.length; j++) { best = Math.max(best, pre[j] - mn); mn = Math.min(mn, pre[j]); }
  return best;
}
